3	/**
4	 * Maps a membership points score to the owner's membership level: 1 for 0-1 points,
5	 * 2 for 2-3, 3 for 4-5 and 4 for 6 or more. The points are computed by
6	 * {@link MembershipPoints}.
7	 */
8	public final class MembershipLevel {
9	
10	    private MembershipLevel() {
11	    }
12	
13	    public static int of(int points) {
14	        if (points <= 1) {
15	            return 1;
16	        }
17	        if (points <= 3) {
18	            return 2;
19	        }
20	        if (points <= 5) {
21	            return 3;
22	        }
23	        return 4;
24	    }
25	}
