5	/**
6	 * Derives the owner's membership number formatted {@code <customerCode>-M<YY>} where
7	 * YY is the last two digits of the registration date's fiscal year (e.g. {@code SMI-0007-M26}).
8	 * The value is a pure function of the owner's own fields, so it needs no stored state.
9	 */
10	public final class MembershipNumber {
11	
12	    private MembershipNumber() {
13	    }
14	
15	    public static String of(String customerCode, LocalDate registrationDate) {
16	        return String.format("%s-M%02d", customerCode, FiscalYear.of(registrationDate) % 100);
17	    }
18	}
