1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Scores an owner's membership points: 2 when an email is on file, 1 when the owner had
7	 * no namesakes at creation (namesakeCount is 0), 2 for a household of three or more, and
8	 * 3 when the owner's tenure exceeds one elapsed fiscal year. {@link MembershipLevel} maps
9	 * the total to a level.
10	 */
11	public final class MembershipPoints {
12	
13	    private static final int TENURE_FISCAL_YEARS = 1;
14	
15	    private MembershipPoints() {
16	    }
17	
18	    public static int of(Integer namesakeCount, String email, LocalDate registrationDate,
19	            boolean goldHousehold) {
20	        int points = 0;
21	        if (email != null && !email.isBlank()) {
22	            points += 2;
23	        }
24	        if (namesakeCount != null && namesakeCount == 0) {
25	            points += 1;
26	        }
27	        if (goldHousehold) {
28	            points += 2;
29	        }
30	        if (registrationDate != null
31	                && FiscalYear.of(LocalDate.now()) - FiscalYear.of(registrationDate) > TENURE_FISCAL_YEARS) {
32	            points += 3;
33	        }
34	        return points;
